  const rm = matchMedia('(prefers-reduced-motion: reduce)'), small = matchMedia('(max-width: 760px)');
  const PAL = ['#22CFA0', '#14C7A8', '#1BBFCB', '#01AEE2', '#0B8FD8', '#0B6BC0', '#0B4FA0', '#0B3F8F'];
